INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (299690, 13473, 'The Economic Times', 'en', 'Sebi proposes to expand FPI play in commodities', 'https://economictimes.indiatimes.com/markets/stocks/news/sebi-proposes-to-expand-fpi-play-in-commodities/articleshow/133167595.cms', 'In a strategic move, the Securities and Exchange Board of India has unveiled plans to enable foreign investors to trade in commodity derivatives. This initiative is designed to expand engagement within India''s commodity derivatives market. International participants will soon be able to trade physically settled non-agricultural contracts, with the requirement to settle positions before the tender period starts.', 'https://img.etimg.com/photo/msid-133167595,imgsize-105672.cms', '2026-08-12T01:11:26+00:00', '2026-08-12T02:16:28.771497'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
