INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (304385, 13473, 'The Hindu BusinessLine', 'en', 'SEBI sees no manipulation in stock closing auction: Chairman Tuhin Kanta Pandey', 'https://www.thehindubusinessline.com/markets/sebi-sees-no-manipulation-in-stock-closing-auction-chairman-tuhin-kanta-pandey/article71335479.ece', 'The closing auction is a big market ‌structure reform in line with global standards, Tuhin Kanta Pandey ‌said at an event in Mumbai.', 'https://bl-i.thgim.com/public/incoming/2hio08/article71335483.ece/alternates/LANDSCAPE_1200/2026-08-12T065607Z_127603075_RC2HTJARTX81_RTRMADP_3_INDIA-STOCKS-CLOSING-AUCTION.JPG', '2026-08-12T07:12:47+00:00', '2026-08-12T07:36:52.188997'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
