INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (307567, 13473, 'The Economic Times', 'en', 'Sebi sees no manipulation in closing auction sessions so far, says Tuhin Kanta Pandey', 'https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-manipulation-in-new-cas-despite-participation-concerns/articleshow/133175145.cms', 'The Securities and Exchange Board of India has confirmed that no manipulation exists within the newly established closing auction system. This session, which establishes closing stock prices, strives to meet international norms. Since its inception, participation in the closing auction has progressively increased. The regulator is actively considering feedback to amplify market participation. This reform is essential in reducing tracking discrepancies for passive investment funds.', 'https://img.etimg.com/photo/msid-133175145,imgsize-72000.cms', '2026-08-12T07:44:45+00:00', '2026-08-12T22:51:54.038962'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
