INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310444, 13473, 'Business Standard', 'hi', 'SEBI Closing Auction Session| Tuhin Kanta Pandey : क्लोजिंग एक्शन सेशन में म्युचुअल फंड्स की कम भागीदारी , सेबी ने बुलाई बैठक - sebi calls meeting over low mutual fund participation in closing action session', 'https://hindi.business-standard.com/markets/sebi-calls-meeting-over-low-mutual-fund-participation-in-closing-action-session-id-544151', '', 'https://hindibusinessstandard.imagibyte.sortdcdn.net/wp-content/uploads/2026/06/Tuhin-Kanta-Pandey-Chairman-SEBI.jpg', '20260812', '2026-08-12T22:59:46.529313'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312178, 13473, 'The Economic Times', 'en', 'Sebi sees no CAS manipulation, eyes more participation', 'https://economictimes.indiatimes.com/markets/stocks/news/sebi-sees-no-cas-manipulation-eyes-more-participation/articleshow/133195469.cms', 'Mumbai: The Securities and Exchange Board of India (Sebi) has not observed any manipulation in the newly introduced closing auction sessions, chairman Tuhin Kanta Pandey said Wednesday, attributing the recent divergence in two major indices to circumspect trader participation in the first few days of the new system."We are considering all inputs to increase participation," Pandey said on the sidelines of the Global Commodity Conclave in Mumbai. Any new mechanism, like the new process to determine closing prices of securities, needs time to settle and attract more participation, Pandey said.The', '', '2026-08-13T00:41:04+00:00', '2026-08-13T01:18:31.119645'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
