INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317618, 13473, 'The Economic Times', 'en', 'UBS upgrades MCX rating to Buy with Rs 3,800 target price: Can it boost the stock?', 'https://economictimes.indiatimes.com/markets/stocks/news/ubs-upgrades-mcx-rating-to-buy-with-rs-3800-target-price-can-it-boost-the-stock/articleshow/133203886.cms', 'Global brokerage UBS upgraded Multi Commodity Exchange of India (MCX) to a Buy rating from Neutral, raising its 12-month price target to Rs 3,800 from Rs 3,600. The upgrade follows a recent 15% price correction from its May peak, which UBS noted leaves the stock trading at an attractive valuation of 40x 12-month forward price-to-earning, a discount of more than 10% to its three-year average.Given this strong valuation support, resilient volumes, and positive regulatory developments, the global brokerage raised its earnings per share estimates for MCX by 4%, 8%, and 9% for FY27, FY28, and FY29,', '', '2026-08-13T07:37:59+00:00', '2026-08-13T08:16:24.203944'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
