INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312147, 13476, 'France 24', 'en', 'Zambia heads to polls with President Hichilema expected to win second term', 'https://www.france24.com/en/africa/20260813-zambia-heads-to-polls-with-president-hichilema-expected-to-win-second-term', 'Zambians vote Thursday in a general election widely expected to give President Hakainde Hichilema a second term, as his economic record faces a test from voters frustrated by the cost of living and opposition parties seek to capitalise on discontent despite deep divisions.', 'https://s.france24.com/media/display/7da626c4-96a8-11f1-8a20-005056bf30b7/w:1024/p:16x9/AP26223850902100.jpg', '2026-08-13T00:33:46+00:00', '2026-08-13T01:17:58.480228'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
