INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (314265, 13476, 'The Guardian', 'en', 'Zambia elections haunted by ghost of incumbent president’s arch-rival', 'https://www.theguardian.com/world/2026/aug/13/zambia-elections-hakainde-hichilema-haunted-ghost-incumbent-president-arch-rival-edgar-lungu', 'Hakainde Hichilema is bidding for second term, but feud between him and family of Edgar Lungu, who died in 2025, continues As Zambians go to the polls, the ghost of the current president’s predecessor hangs over the elections. Hakainde Hichilema, 64, is bidding for a second term leading the southern African country after defeating his arch-rival Edgar Lungu by a landslide in 2021. Continue reading...', 'https://i.guim.co.uk/img/media/7fb7bd10ff23989b0737c787f520bde17fc8ae97/0_0_4731_3785/master/4731.jpg?width=140&quality=85&auto=format&fit=max&s=5f09ed662705d0ebc4d6d90bb21b8f5c', '2026-08-13T04:00:49+00:00', '2026-08-13T04:28:13.544188'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
