INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329344, 13476, 'Associated Press', 'en', 'Zambia suspends vote counting in election over reports of violence and the theft of ballot papers', 'https://news.google.com/rss/articles/CBMioAFBVV95cUxNZS1vOGdEXzFqSE9VdHZkblc0dlV0Qi05YjRrZER5eGFhT21neW1iTWNWSHgtOExPem1zQnBDVmtrS3JoaWMwM1laQ1lPWDJleU9IbmtUVE1oaVJzcHM5b3F3N1FTdGk0aUVLZ3ZuVlQ2R0g0WmRTS3VDRE9Edk95Y1htNlNvMHZadUlORHVIcGMyVlVBcFRpbUxaamNFQW5H?oc=5', 'Zambia suspends vote counting in election over reports of violence and the theft of ballot papers AP News', '', '2026-08-14T13:01:00+00:00', '2026-08-14T14:58:09.122074'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329369, 13476, 'BBC News', 'en', 'Presidential vote counting halted in Zambia over alleged attacks on polling staff', 'https://www.bbc.co.uk/news/articles/c5yr8r04edvo', 'The electoral commission said violence had "resulted in the theft of marked ballot papers".', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/3018/live/da9b86e0-97b0-11f1-a7ab-8b30adf0800a.jpg', '2026-08-14T11:37:31+00:00', '2026-08-14T14:58:11.365720'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (329530, 13476, 'France 24', 'en', 'Zambia suspends vote count nationwide amid reports of violence, ballot theft', 'https://www.france24.com/en/africa/20260814-zambia-suspends-election-vote-counting-over-reports-of-violence', 'Zambia''s electoral commission on Friday suspended vote counting from Thursday''s presidential and parliamentary elections for at least 24 hours due to “violence targeted at poll staff” and reported instances of theft of marked ballot papers. Former minister Brian Mundubile, the main challenger to President Hakainde Hichilema, claimed a first-round victory and said his camp viewed "the continued delay ... with grave concern".', 'https://s.france24.com/media/display/4ed5b6a4-97d7-11f1-9fe0-005056bf30b7/w:1024/p:16x9/fde95d622020d705e303b29b9aa9f9eaa2522446.jpg', '2026-08-14T11:57:23+00:00', '2026-08-14T14:58:37.108830'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
