INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333790, 13476, 'The New York Times', 'en', 'Zambia Halts Presidential Election Vote Count Over Violence and Fraud Allegations', 'https://www.nytimes.com/2026/08/14/world/africa/zambia-election-vote-count-suspended-president.html', 'The electoral commission for the southern African nation said poll workers had been attacked and ballots had been stolen as both top candidates claimed leads.', 'https://static01.nyt.com/images/2026/08/14/multimedia/14int-zambia-election-1-jkfg/14int-zambia-election-1-jkfg-mediumSquareAt3X.jpg', '2026-08-14T15:24:55+00:00', '2026-08-14T17:18:54.034053'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (333886, 13476, 'The Independent', 'en', 'Zambia election chaos erupts as vote count halted over alleged violence and ballot paper theft', 'https://www.independent.co.uk/news/world/africa/zambia-election-vote-count-suspended-violence-b3033268.html', 'The Zambian commission indicated it would review the decision to suspend the vote count in 24 hours', 'https://static.independent.co.uk/2026/08/14/16/2026-08-13T185314Z_124103773_RC2RXMAD2SVW_RTRMADP_3_ZAMBIA-ELECTION.JPG?width=1200&auto=webp&trim=0%2C277%2C0%2C277', '2026-08-14T15:17:56+00:00', '2026-08-14T17:19:51.393245'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
