INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (297682, 13484, 'Amar Ujala', 'hi', 'राम मंदिर: CEO चयन में 34 सवालों की कसौटी, अंतिम फैसला ट्रस्ट का; कार्यकारी को स्वतंत्र निर्णय का अधिकार नहीं', 'https://www.amarujala.com/haryana/sirsa/ayodhya-a-34-question-criterion-for-selecting-the-ram-mandir-ceo-2026-08-12', 'श्रीराम जन्मभूमि तीर्थ क्षेत्र ट्रस्ट के मुख्य कार्यकारी अधिकारी (सीईओ) के चयन की प्रक्रिया में अभ्यर्थियों के लिए 34 बिंदुओं वाला विस्तृत मूल्यांकन प्रारूप तैयार किया गया था।', '', '2026-08-11T22:46:55+00:00', '2026-08-11T23:20:40.295436'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (299539, 13484, 'Aaj Tak', 'hi', '''शराब पीते हैं, जनेऊ पहनते हैं?'', राम मंदिर CEO पद के इंटरव्यू में पूछे गए ये सवाल', 'https://www.aajtak.in/uttar-pradesh/story/ram-mandir-ceo-selection-interview-day-1-questions-alcohol-non-veg-ntc-drmt-rpti-2620306-2026-08-12', 'राम मंदिर ट्रस्ट ने CEO पद के लिए 11 अगस्त से इंटरव्यू शुरू कर दिए हैं. देशभर से आए 5300 से ज्यादा आवेदनों में से 18 योग्य उम्मीदवारों को इंटरव्यू के लिए शॉर्टलिस्ट किया गया है. पहले दिन 10 लोगों का इंटरव्यू लिया जा चुका है, जिनसे उनकी आस्था, प्रशासनिक पदों पर काम करने के अनुभव और विजन को लेकर सवाल किए गए.', '', '2026-08-12T01:28:26+00:00', '2026-08-12T02:14:24.345523'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (301073, 13484, 'Aaj Tak', 'hi', 'Ram Mandir CEO का इंटरव्यू शुरू! जानिए पूछे जा रहे कैसे सवाल?', 'https://www.aajtak.in/short-videos/video/ram-mandir-trust-ceo-selection-interviews-begin-18-shortlisted-candidates-final-panel-to-be-announced-september-mmta-2620382-2026-08-12', 'अयोध्या राम मंदिर ट्रस्ट के सीईओ पद के चयन की प्रक्रिया अंतिम चरण में पहुंच गई है. 5,300 से ज्यादा आवेदनों में से 18 उम्मीदवारों को साक्षात्कार के लिए चुना गया है. 11 और 12 अगस्त को होने वाले साक्षात्कार में प्रशासनिक अनुभव, मंदिर प्रबंधन, धार्मिक संस्थाओं के संचालन और भीड़ व्यवस्था से जुड़े सवाल पूछे जा रहे हैं. चयन समिति 2 सितंबर तक तीन नामों का पैनल ट्रस्ट को सौंपेगी.', '', '2026-08-12T04:45:49+00:00', '2026-08-12T06:07:30.821623'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (302898, 13484, 'Navbharat Times', 'hi', 'शाकाहारी हैं ? शराब तो नहीं पीते ? राम मंदिर CEO के लिए अयोध्या में शुरू हुए इंटरव्यू , विजन पर भी पूछे जा रहे सवाल', 'https://navbharattimes.indiatimes.com/state/uttar-pradesh/ayodhya/ram-mandir-ceo-interview-begun-eight-candidates-interviewed/amp_articleshow/133167671.cms', '', 'https://static.langimg.com/nbt/thumb/133167689/ram-mandir-ceo-interview.jpg?imgsize=502395&resizemode=75', '20260812', '2026-08-12T06:16:23.204392'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
