INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312970, 13484, 'Aaj Tak', 'hi', 'Ayodhya Ram Mandir को जल्द मिलेगा पहला CEO', 'https://www.aajtak.in/short-videos/video/ram-mandir-ceo-selection-interviews-complete-three-names-panel-next-as-trust-prepares-final-appointment-mmta-2620995-2026-08-13', 'अयोध्या राम मंदिर के पहले सीईओ की चयन प्रक्रिया अब निर्णायक मोड़ पर पहुंच गई है. 5,585 आवेदनों से शुरू हुई दौड़ 16 अंतिम उम्मीदवारों तक पहुंची और 11-12 अगस्त को अंतिम इंटरव्यू पूरे हुए. अब चयन समिति सभी उम्मीदवारों के अनुभव, नेतृत्व क्षमता और योग्यता का मूल्यांकन करेगी. इसके बाद तीन नामों का पैनल श्रीराम जन्मभूमि तीर्थ क्षेत्र ट्रस्ट को सौंपा जाएगा. अंतिम नियुक्ति का फैसला ट्रस्ट करेगा.', '', '2026-08-13T02:34:32+00:00', '2026-08-13T02:48:24.139024'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (312978, 13484, 'The Lallantop', 'hi', 'मीट खाते हैं, शराब पीते हैं, जनेऊ पहना है? राम मंदिर ट्रस्ट के CEO कैंडिडेट्स से पूछे गए ऐसे सवाल | The Lallantop', 'https://news.google.?oc=5', 'मीट खाते हैं, शराब पीते हैं, जनेऊ पहना है? राम मंदिर ट्रस्ट के CEO कैंडिडेट्स से पूछे गए ऐसे सवाल | The Lallantop The Lallantop', '', '2026-08-12T11:08:24+00:00', '2026-08-13T02:48:32.351743'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (313472, 13484, 'Aaj Tak', 'hi', '''भीड़ कैसे मैनेज करोगे और पहनावा कैसा रहेगा?'', राम मंदिर CEO इंटरव्यू के 35 सवाल', 'https://www.aajtak.in/uttar-pradesh/story/ayodhya-ram-mandir-ceo-interview-completed-for-shortlisted-candidates-ntc-ksrj-rpti-2621021-2026-08-13', 'अयोध्या राम मंदिर के मुख्य कार्यकारी अधिकारी (CEO) पद के लिए 18 उम्मीदवारों का इंटरव्यू प्रक्रिया पूरी हो गई है. तीन सदस्यीय चयन समिति ने 35 सवालों के जरिए उम्मीदवारों की प्रशासनिक क्षमता, क्राउड मैनेजमेंट, 20 साल के अनुभव के साथ-साथ चोटी, जनेऊ, शाकाहार और धार्मिक आस्था को भी परखा.', '', '2026-08-13T03:04:16+00:00', '2026-08-13T03:34:40.735069'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
