INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (314055, 13494, 'The Times of India', 'en', 'NEET-PG aspirants get wrong exam city texts after NBEMS glitch', 'https://timesofindia.indiatimes.com/india/neet-pg-aspirants-get-wrong-exam-city-texts-after-nbems-glitch/articleshow/133196961.cms', 'NEET-PG 2026 aspirants received incorrect SMS alerts regarding their allotted examination cities. A technical glitch caused the National Board of Examinations in Medical Sciences to send wrong messages. The board has since issued corrected SMSes and emails to affected candidates. Aspirants are advised to verify their exam city details on the official NBEMS applicant portal. Candidates should rely only on official communications and avoid misinformation.', 'https://static.toiimg.com/photo/msid-133197049,imgsize-53964.cms', '2026-08-13T03:44:42+00:00', '2026-08-13T04:26:09.895153'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
