INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (300129, 13580, 'The Times of India', 'en', 'Ronaldo wedding: Did Messi, Mbappé, Haaland and Harry Kane really attend?', 'https://timesofindia.indiatimes.com/sports/football/top-stories/fact-check-did-lionel-messi-kylian-mbapp-erling-haaland-and-harry-kane-really-attend-the-cristiano-ronaldo-wedding/articleshow/133168101.cms', 'Cristiano Ronaldo and Georgina Rodriguez have officially married after a decade together. Viral images claiming to show Lionel Messi and others at the wedding are fake. These images were digitally manipulated or created using artificial intelligence. The couple kept their intimate ceremony in Portugal extremely private. Social media users should verify information and avoid mistaking fake content for reality.', 'https://static.toiimg.com/photo/msid-133168201,imgsize-181136.cms', '2026-08-12T02:33:40+00:00', '2026-08-12T03:09:00.284840'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
